html:
{%- set currency = doc.currency or "NGN" -%}

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>Salary Slip — {{ doc.name }}</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700;900&family=DM+Sans:wght@300;400;500;600;700&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --ink:        #0d1b2a;
    --ink-soft:   #455a64;
    --rule:       #cfd8dc;
    --accent:     #1a237e;
    --accent-lt:  #e8eaf6;
    --gold:       #c8920a;
    --gold-lt:    #fff8e1;
    --green:      #1b5e20;
    --red:        #b71c1c;
    --paper:      #fafafa;
  }

  @page {
    size: A4;
    margin: 12mm 10mm;
  }

  body {
    font-family: 'DM Sans', sans-serif;
    font-size: 10pt;
    color: var(--ink);
    background: var(--paper);
    line-height: 1.5;
  }

  .document {
    max-width: 100%;
    margin: 0 auto;
    padding: 0;
  }

  /* ── HEADER ───────────────────────────────────── */
  .header {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: start;
    gap: 24px;
    border-bottom: 3px solid var(--accent);
    padding-bottom: 18px;
    margin-bottom: 24px;
  }

  .company-block h1 {
    font-family: 'Playfair Display', serif;
    font-size: 22pt;
    font-weight: 900;
    color: var(--accent);
    letter-spacing: -0.5px;
    line-height: 1.1;
  }

  .company-block p {
    color: var(--ink-soft);
    font-size: 9pt;
    margin-top: 4px;
  }

  .doc-meta {
    text-align: right;
  }

  .doc-number {
    font-family: 'Playfair Display', serif;
    font-size: 16pt;
    font-weight: 700;
    color: var(--accent);
  }

  .doc-label {
    font-size: 8pt;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--gold);
    font-weight: 600;
    display: block;
    margin-bottom: 4px;
  }

  /* ── EMPLOYEE BLOCK ──────────────────────────────── */
  .employee-block {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
    margin-bottom: 22px;
    background: var(--accent-lt);
    border-radius: 8px;
    padding: 16px 20px;
    border-top: 3px solid var(--accent);
  }

  .emp-item .lbl {
    font-size: 8pt;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--ink-soft);
    font-weight: 600;
  }

  .emp-item .val {
    font-family: 'Playfair Display', serif;
    font-size: 13pt;
    font-weight: 700;
    color: var(--ink);
    margin-top: 2px;
  }

  /* ── META GRID ────────────────────────────────── */
  .meta-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--rule);
    border: 1px solid var(--rule);
    border-radius: 6px;
    overflow: hidden;
    margin-bottom: 22px;
  }

  .meta-cell {
    background: #fff;
    padding: 10px 13px;
  }

  .meta-cell .lbl { font-size: 8pt; color: var(--ink-soft); text-transform: uppercase; letter-spacing: 1px; }
  .meta-cell .val { font-size: 10.5pt; font-weight: 600; margin-top: 2px; }

  /* ── SECTION TITLES ───────────────────────────── */
  .section-title {
    font-family: 'Playfair Display', serif;
    font-size: 11pt;
    font-weight: 700;
    color: var(--accent);
    border-bottom: 2px solid var(--accent);
    padding-bottom: 5px;
    margin: 22px 0 12px;
    letter-spacing: 0.2px;
  }

  .section-title span {
    font-family: 'DM Sans', sans-serif;
    font-size: 8pt;
    color: var(--ink-soft);
    font-weight: 400;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-left: 8px;
  }

  /* ── TABLES ───────────────────────────────────── */
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 9pt;
    table-layout: auto;
  }

  thead tr {
    background: var(--accent);
    color: #fff;
  }

  thead th {
    padding: 9px 8px;
    text-align: right;
    font-weight: 600;
    letter-spacing: 0.3px;
    font-size: 8pt;
    white-space: nowrap;
  }

  thead th:first-child { text-align: left; }

  tbody tr:nth-child(even) { background: #f5f5f5; }
  tbody tr:hover { background: var(--accent-lt); }

  tbody td {
    padding: 8px 8px;
    text-align: right;
    border-bottom: 1px solid var(--rule);
    vertical-align: top;
  }

  tbody td:first-child { text-align: left; }

  tfoot tr {
    background: var(--accent-lt);
    font-weight: 700;
    border-top: 2px solid var(--accent);
  }

  tfoot td {
    padding: 9px 8px;
    text-align: right;
  }

  tfoot td:first-child { text-align: left; }

  /* ── EARNINGS TABLE ─────────────────────────────── */
  .earnings-table thead tr { background: var(--green); }
  .earnings-table tfoot tr { background: #e8f5e9; border-top: 2px solid var(--green); }

  /* ── DEDUCTIONS TABLE ───────────────────────────── */
  .deductions-table thead tr { background: var(--red); }
  .deductions-table tfoot tr { background: #ffebee; border-top: 2px solid var(--red); }

  /* ── TOTALS BLOCK ─────────────────────────────── */
  .totals-block {
    margin-left: auto;
    width: 340px;
    border: 1px solid var(--rule);
    border-radius: 8px;
    overflow: hidden;
    margin-top: 14px;
  }

  .totals-block table thead tr { background: #37474f; }

  .grand-row td {
    background: var(--accent) !important;
    color: #fff !important;
    font-size: 12pt !important;
    font-family: 'Playfair Display', serif;
    padding: 11px 14px !important;
  }

  .num { font-variant-numeric: tabular-nums; }

  /* ── PAYMENT SUMMARY ────────────────────────────── */
  .payment-summary {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
    margin: 22px 0;
  }

  .pay-box {
    background: #fff;
    border: 1px solid var(--rule);
    border-radius: 8px;
    padding: 14px 16px;
    text-align: center;
  }

  .pay-box .lbl {
    font-size: 8pt;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--ink-soft);
  }

  .pay-box .val {
    font-family: 'Playfair Display', serif;
    font-size: 16pt;
    font-weight: 700;
    margin-top: 4px;
  }

  .pay-box.gross .val { color: var(--green); }
  .pay-box.deductions .val { color: var(--red); }
  .pay-box.net .val { color: var(--accent); }

  /* ── FOOTER ───────────────────────────────────── */
  .doc-footer {
    border-top: 2px solid var(--accent);
    margin-top: 32px;
    padding-top: 14px;
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
    font-size: 8.5pt;
    color: var(--ink-soft);
  }

  .sig-line {
    border-top: 1px solid var(--ink);
    margin-top: 36px;
    padding-top: 5px;
    font-size: 8pt;
    color: var(--ink-soft);
  }

  .watermark {
    text-align: center;
    margin-top: 8px;
    font-size: 7.5pt;
    color: #b0bec5;
    letter-spacing: 1px;
  }

  .notice {
    background: var(--gold-lt);
    border: 1px solid var(--gold);
    border-left: 4px solid var(--gold);
    border-radius: 6px;
    padding: 10px 14px;
    font-size: 9pt;
    color: #5d4037;
    margin: 14px 0;
  }

  .badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 10px;
    font-size: 7.5pt;
    font-weight: 600;
    color: #fff;
  }
  .badge-earn { background: var(--green); }
  .badge-ded  { background: var(--red); }

  /* ── COMPONENTS LIST ────────────────────────────── */
  .component-list {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin: 14px 0;
  }

  .comp-group {
    border: 1px solid var(--rule);
    border-radius: 6px;
    overflow: hidden;
  }

  .comp-group .heading {
    padding: 8px 12px;
    font-weight: 700;
    font-size: 9pt;
    color: #fff;
  }

  .comp-group .heading.earn-head { background: var(--green); }
  .comp-group .heading.ded-head  { background: var(--red); }

  .comp-group table {
    font-size: 9pt;
  }

  .comp-group table td {
    padding: 6px 12px;
    border-bottom: 1px solid var(--rule);
    text-align: right;
  }

  .comp-group table td:first-child { text-align: left; }

  .comp-group table tr:last-child td { border-bottom: none; }
</style>
</head>
<body>
<div class="document">

  <!-- ═══════════════════════════════════════════
       HEADER
  ══════════════════════════════════════════════ -->
  <div class="header">
    <div class="company-block">
      <h1>{{ doc.company or "Company Name" }}</h1>
      <p>Official Salary Slip</p>
      <p style="margin-top:6px;font-size:9pt;color:var(--gold);font-weight:600;letter-spacing:1px;text-transform:uppercase;">
        Payroll Period: {{ doc.start_date and frappe.format_date(doc.start_date) or "" }} 
        {% if doc.start_date and doc.end_date %}—{% endif %} 
        {{ doc.end_date and frappe.format_date(doc.end_date) or "" }}
      </p>
    </div>
    <div class="doc-meta">
      <span class="doc-label">Salary Slip No.</span>
      <div class="doc-number">{{ doc.name }}</div>
      <div style="margin-top:6px;font-size:9pt;color:var(--ink-soft);">
        Generated: <strong>{{ frappe.format_date(frappe.utils.nowdate()) }}</strong>
      </div>
      <div style="margin-top:4px;font-size:9pt;color:var(--ink-soft);">
        Status: <strong>{{ doc.status or "Approved" }}</strong>
      </div>
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       EMPLOYEE BLOCK
  ══════════════════════════════════════════════ -->
  <div class="employee-block">
    <div class="emp-item">
      <div class="lbl">Employee</div>
      <div class="val">{{ doc.employee_name }}</div>
      <div style="font-size:9pt;color:var(--ink-soft);margin-top:2px;">{{ doc.employee }}</div>
    </div>
    <div class="emp-item">
      <div class="lbl">Department / Designation</div>
      <div class="val">{{ doc.department or "—" }}</div>
      <div style="font-size:9pt;color:var(--ink-soft);margin-top:2px;">{{ doc.designation or "—" }}</div>
    </div>
    <div class="emp-item">
      <div class="lbl">Payment Details</div>
      <div class="val">{{ doc.bank_name or "—" }}</div>
      <div style="font-size:9pt;color:var(--ink-soft);margin-top:2px;">
        Acct: {{ doc.bank_account_no or "—" }}
      </div>
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       META GRID
  ══════════════════════════════════════════════ -->
  <div class="meta-grid">
    <div class="meta-cell">
      <div class="lbl">Payroll Period</div>
      <div class="val">
        {{ doc.start_date and frappe.format_date(doc.start_date) or "" }}
        {% if doc.start_date and doc.end_date %}to{% endif %}
        {{ doc.end_date and frappe.format_date(doc.end_date) or "" }}
      </div>
    </div>
    <div class="meta-cell">
      <div class="lbl">Payment Days</div>
      <div class="val">{{ doc.payment_days or doc.working_days or "—" }}</div>
    </div>
    <div class="meta-cell">
      <div class="lbl">Currency</div>
      <div class="val">{{ doc.currency or "NGN" }}</div>
    </div>
    <div class="meta-cell">
      <div class="lbl">Payable On</div>
      <div class="val">{{ doc.payroll_date or "—" }}</div>
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       COMPONENT LIST (EARNINGS & DEDUCTIONS)
       FILTER: show_on_payroll_report == 1 or 0 (show all if field doesn't exist)
  ══════════════════════════════════════════════ -->
  <div class="component-list">
    <!-- EARNINGS -->
    <div class="comp-group">
      <div class="heading earn-head">EARNINGS</div>
      <table>
        <tbody>
          {% set earnings_visible = [] %}
          {% for row in doc.earnings %}
            {# Show if show_on_payroll_report is 1 OR if the field doesn't exist (show all) #}
            {% if row.show_on_payroll_report is not defined or row.show_on_payroll_report == 1 %}
              {% set _ = earnings_visible.append(1) %}
              <tr>
                <td>
                  <span class="badge badge-earn">+</span>
                  {{ row.salary_component }}
                  {% if row.abbr %}
                  <span style="font-size:7pt;color:var(--ink-soft);">({{ row.abbr }})</span>
                  {% endif %}
                </td>
                <td class="num">{{ row.get_formatted("amount") or row.amount }}</td>
              </tr>
            {% endif %}
          {% endfor %}
          {% if earnings_visible|length == 0 %}
            <tr>
              <td colspan="2" style="text-align:center;color:var(--ink-soft);font-style:italic;padding:12px;">
                No earnings to display
              </td>
            </tr>
          {% endif %}
        </tbody>
        <tfoot>
          <tr>
            <td><strong>Total Earnings</strong></td>
            <td class="num" style="color:var(--green);font-weight:700;">
              {{ doc.get_formatted("gross_pay") or doc.gross_pay }}
            </td>
          </tr>
        </tfoot>
      </table>
    </div>

    <!-- DEDUCTIONS -->
    <div class="comp-group">
      <div class="heading ded-head">DEDUCTIONS</div>
      <table>
        <tbody>
          {% set deductions_visible = [] %}
          {% for row in doc.deductions %}
            {# Show if show_on_payroll_report is 1 OR if the field doesn't exist (show all) #}
            {% if row.show_on_payroll_report is not defined or row.show_on_payroll_report == 1 %}
              {% set _ = deductions_visible.append(1) %}
              <tr>
                <td>
                  <span class="badge badge-ded">−</span>
                  {{ row.salary_component }}
                  {% if row.abbr %}
                  <span style="font-size:7pt;color:var(--ink-soft);">({{ row.abbr }})</span>
                  {% endif %}
                </td>
                <td class="num">{{ row.get_formatted("amount") or row.amount }}</td>
              </tr>
            {% endif %}
          {% endfor %}
          {% if deductions_visible|length == 0 %}
            <tr>
              <td colspan="2" style="text-align:center;color:var(--ink-soft);font-style:italic;padding:12px;">
                No deductions to display
              </td>
            </tr>
          {% endif %}
        </tbody>
        <tfoot>
          <tr>
            <td><strong>Total Deductions</strong></td>
            <td class="num" style="color:var(--red);font-weight:700;">
              {{ doc.get_formatted("total_deduction") or doc.total_deduction }}
            </td>
          </tr>
        </tfoot>
      </table>
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       PAYMENT SUMMARY
  ══════════════════════════════════════════════ -->
  <div class="payment-summary">
    <div class="pay-box gross">
      <div class="lbl">Gross Pay</div>
      <div class="val">{{ doc.get_formatted("gross_pay") or doc.gross_pay }}</div>
    </div>
    <div class="pay-box deductions">
      <div class="lbl">Total Deductions</div>
      <div class="val">{{ doc.get_formatted("total_deduction") or doc.total_deduction }}</div>
    </div>
    <div class="pay-box net">
      <div class="lbl">Net Pay</div>
      <div class="val">{{ doc.get_formatted("net_pay") or doc.net_pay }}</div>
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       DETAILED TOTALS TABLE
  ══════════════════════════════════════════════ -->
  <div style="display:flex;justify-content:flex-end;">
    <div class="totals-block">
      <table>
        <thead>
          <tr><th colspan="2" style="text-align:center;letter-spacing:2px;font-size:9pt;">SALARY SUMMARY</th></tr>
        </thead>
        <tbody>
          <tr>
            <td style="text-align:left;">Gross Earnings</td>
            <td class="num">{{ doc.get_formatted("gross_pay") or doc.gross_pay }}</td>
          </tr>
          <tr>
            <td style="text-align:left;">Total Deductions</td>
            <td class="num" style="color:var(--red);">
              ({{ doc.get_formatted("total_deduction") or doc.total_deduction }})
            </td>
          </tr>
          {% if doc.tax_amount %}
          <tr>
            <td style="text-align:left;padding-left:20px;font-size:8.5pt;color:var(--ink-soft);">
              └ PAYE Tax
            </td>
            <td class="num" style="font-size:8.5pt;">{{ doc.get_formatted("tax_amount") }}</td>
          </tr>
          {% endif %}
          {% if doc.pension_amount %}
          <tr>
            <td style="text-align:left;padding-left:20px;font-size:8.5pt;color:var(--ink-soft);">
              └ Pension
            </td>
            <td class="num" style="font-size:8.5pt;">{{ doc.get_formatted("pension_amount") }}</td>
          </tr>
          {% endif %}
          {% if doc.nhif_amount %}
          <tr>
            <td style="text-align:left;padding-left:20px;font-size:8.5pt;color:var(--ink-soft);">
              └ NHIF
            </td>
            <td class="num" style="font-size:8.5pt;">{{ doc.get_formatted("nhif_amount") }}</td>
          </tr>
          {% endif %}
          {% if doc.nssf_amount %}
          <tr>
            <td style="text-align:left;padding-left:20px;font-size:8.5pt;color:var(--ink-soft);">
              └ NSSF
            </td>
            <td class="num" style="font-size:8.5pt;">{{ doc.get_formatted("nssf_amount") }}</td>
          </tr>
          {% endif %}
        </tbody>
        <tfoot>
          <tr class="grand-row">
            <td style="text-align:left;">NET PAY</td>
            <td class="num">{{ doc.get_formatted("net_pay") or doc.net_pay }}</td>
          </tr>
        </tfoot>
      </table>
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       REMARKS / NOTES
  ══════════════════════════════════════════════ -->
  {% if doc.remarks %}
  <div class="notice" style="margin-top:22px;">
    <strong>📝 Remarks:</strong> {{ doc.remarks }}
  </div>
  {% endif %}

  <!-- ═══════════════════════════════════════════
       FOOTER / SIGNATURES
  ══════════════════════════════════════════════ -->
  <div class="doc-footer">
    <div>
      <div class="sig-line">Prepared by (HR / Payroll)</div>
    </div>
    <div>
      <div class="sig-line">Reviewed by (Finance)</div>
    </div>
    <div>
      <div class="sig-line">Approved by (GM / CEO)</div>
    </div>
  </div>

  <div class="watermark" style="margin-top:18px;">
    Generated by ERPNext · {{ doc.company or "Company" }} · {{ doc.name }} ·
    {{ frappe.format_date(frappe.utils.nowdate()) }}
    · This is a computer-generated document and does not require a physical signature.
  </div>

</div>
</body>
</html>
